import type { ToolAssignment, Tool } from "../types";

export function exportToolAssignmentsPDF(
  assignments: ToolAssignment[],
  tools: Tool[],
  title = "Tool Access & Permissions Assignment Matrix"
): boolean {
  const total = assignments.length;
  const activeCount = assignments.filter((a) => !a.revoked_at).length;
  const revokedCount = assignments.filter((a) => a.revoked_at).length;

  const getToolName = (toolId: number) => {
    const t = tools.find((tool) => tool.id === toolId);
    return t ? t.name : `Tool #${toolId}`;
  };

  const rows = assignments.length > 0
    ? assignments
        .map((a) => {
          const empName = a.employees ? `${a.employees.first_name} ${a.employees.last_name}` : "Employee";
          const dept = a.employees?.department || "—";
          const role = a.employees?.role || "—";
          const toolName = getToolName(a.tool_id);
          const assignedDate = a.assigned_at ? new Date(a.assigned_at).toLocaleDateString() : "—";
          const isRevoked = !!a.revoked_at;

          const statColor = isRevoked
            ? "background:#fee2e2;color:#991b1b"
            : "background:#d1fae5;color:#065f46";

          return `<tr>
            <td style="font-weight:700;color:#253C7D">${empName}<br/><span style="font-size:10px;color:#64748b">${dept} &middot; ${role}</span></td>
            <td style="font-weight:600">${toolName}</td>
            <td>${assignedDate}</td>
            <td>${a.revoked_at ? new Date(a.revoked_at).toLocaleDateString() : "—"}</td>
            <td>
              <span style="display:inline-block;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;${statColor}">
                ${isRevoked ? "REVOKED" : "AUTHORIZED"}
              </span>
            </td>
          </tr>`;
        })
        .join("")
    : `<tr><td colspan="5" style="text-align:center;padding:24px;color:#64748b;">No tool assignments found.</td></tr>`;

  const html = `<!DOCTYPE html>
  <html>
  <head>
    <title>${title}</title>
    <style>
      @page { size: A4 landscape; margin: 15mm; }
      body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; margin: 0; padding: 24px; color: #1e293b; }
      .header-box { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #253C7D; padding-bottom: 14px; margin-bottom: 18px; }
      h1 { font-size: 20px; font-weight: 800; color: #253C7D; margin: 0 0 4px 0; }
      .meta { font-size: 11px; color: #64748b; }
      .stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 18px; }
      .stat-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 10px 14px; text-align: center; }
      .stat-val { font-size: 18px; font-weight: 800; color: #253C7D; }
      .stat-lbl { font-size: 10px; font-weight: 700; color: #64748b; text-transform: uppercase; margin-top: 2px; }
      table { width: 100%; border-collapse: collapse; margin-top: 8px; font-size: 11px; }
      th { text-align: left; padding: 8px 8px; background: #253C7D; color: #fff; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; }
      td { padding: 7px 8px; border-bottom: 1px solid #f1f5f9; }
      tr:nth-child(even) { background-color: #f8fafc; }
      .footer { margin-top: 24px; font-size: 10px; color: #94a3b8; display: flex; justify-content: space-between; border-top: 1px solid #e2e8f0; padding-top: 8px; }
    </style>
  </head>
  <body>
    <div class="header-box">
      <div>
        <h1>HRM_OPS — ${title}</h1>
        <div class="meta">Access Governance &middot; User Permission Matrix</div>
      </div>
      <div class="meta" style="text-align:right">
        <div><strong>Generated:</strong> ${new Date().toLocaleString("en-US")}</div>
        <div><strong>Total Grants:</strong> ${total} Records</div>
      </div>
    </div>

    <div class="stats-grid">
      <div class="stat-card"><div class="stat-val">${total}</div><div class="stat-lbl">Total Grants Logged</div></div>
      <div class="stat-card"><div class="stat-val" style="color:#059669">${activeCount}</div><div class="stat-lbl">Active Permissions</div></div>
      <div class="stat-card"><div class="stat-val" style="color:#dc2626">${revokedCount}</div><div class="stat-lbl">Revoked Permissions</div></div>
    </div>

    <table>
      <thead>
        <tr>
          <th>Employee Details</th>
          <th>Tool Application</th>
          <th>Granted Date</th>
          <th>Revoked Date</th>
          <th>Permission Status</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>

    <div class="footer">
      <div>HRM_OPS Enterprise HRMS &middot; Tool Access Governance</div>
      <div>Page 1 of 1</div>
    </div>
  </body>
  </html>`;

  const w = window.open("", "_blank");
  if (w) {
    w.document.write(html);
    w.document.close();
    setTimeout(() => w.print(), 400);
  }
  return true;
}
